head.b:skin:
:root {
    --bg: #030406;
    --card: #0a0d14;
    --accent: #10b981;
    --gold: #d4af37;
    --text: #f3f4f6;
    --border: rgba(212, 175, 55, 0.15);
}

* { box-sizing: border-box; scroll-behavior: smooth; }
body { 
    background: var(--bg); color: var(--text); 
    font-family: 'Plus Jakarta Sans', sans-serif; 
    margin: 0; padding: 15px; min-height: 100vh;
}

.container { width: 100%; max-width: 1200px; margin: 0 auto; transition: 0.4s ease; }

/* ZEN MODE LOGIC */
.zen-active .side-panel { display: none; }
.zen-active .display-area { flex: 1; }
.zen-active .container { max-width: 800px; }

header { 
    display: flex; justify-content: space-between; align-items: center;
    padding-bottom: 20px; border-bottom: 1px solid var(--border); margin-bottom: 30px;
    position: sticky; top: 0; background: var(--bg); z-index: 100;
}
.brand h1 { font-size: 1rem; font-weight: 800; letter-spacing: 2px; margin: 0; color: var(--gold); text-transform: uppercase; }

.main-grid { display: flex; flex-wrap: wrap; gap: 25px; }
.side-panel { flex: 1 1 350px; background: var(--card); border-radius: 24px; padding: 25px; border: 1px solid var(--border); height: fit-content; }
.display-area { flex: 2 1 500px; min-width: 0; }

label { display: block; font-size: 0.65rem; font-weight: 800; color: #4b5563; text-transform: uppercase; letter-spacing: 2px; margin: 15px 0 6px 0; }
select, input, textarea { width: 100%; background: #000; border: 1px solid #1f2937; color: white; padding: 12px; border-radius: 12px; font-size: 0.85rem; outline: none; transition: 0.3s; }
select:focus, input:focus, textarea:focus { border-color: var(--gold); box-shadow: 0 0 10px rgba(212,175,55,0.1); }

.btn-forge { width: 100%; background: var(--gold); color: #000; border: none; padding: 18px; border-radius: 14px; font-weight: 800; cursor: pointer; margin-top: 25px; text-transform: uppercase; font-size: 0.8rem; letter-spacing: 1px; }
.btn-reset { width: 100%; background: transparent; border: 1px solid #ef4444; color: #ef4444; padding: 12px; border-radius: 12px; font-weight: 800; cursor: pointer; margin-top: 10px; text-transform: uppercase; font-size: 0.7rem; letter-spacing: 1px; }

.btn-zen { 
    background: var(--gold); border: none; color: #000; 
    padding: 8px 18px; border-radius: 25px; font-size: 0.65rem; 
    font-weight: 800; cursor: pointer; transition: 0.3s;
}
.zen-active .btn-zen { background: #ef4444; color: #fff; }

.artifact-list { display: flex; flex-direction: column; gap: 20px; }
.artifact-card { background: #000; border-radius: 24px; padding: 20px; border: 1px solid var(--border); animation: slideUp 0.4s ease forwards; }
.artifact-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
.artifact-tag { font-size: 0.6rem; color: var(--gold); font-weight: 800; letter-spacing: 2px; text-transform: uppercase; }

pre { background: #050505; color: var(--accent); padding: 18px; border-radius: 14px; font-size: 0.75rem; border: 1px solid #111827; font-family: 'Courier New', monospace; white-space: pre-wrap; word-break: break-all; margin: 0; }
.copy-btn { background: var(--accent); color: #000; border: none; padding: 6px 14px; border-radius: 8px; font-size: 0.6rem; font-weight: 800; cursor: pointer; }

@keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 768px) {
    .side-panel { flex: 1 1 100%; }
    header { padding: 10px 0; }
}

body.script:
//
function toggleZen() { 
    const app = document.getElementById('mainApp');
    const btn = document.getElementById('zenToggle');
    app.classList.toggle('zen-active');
    btn.innerHTML = app.classList.contains('zen-active') ? 'ZEN MODE: ON' : 'ZEN MODE: OFF';
}

function resetEngine() {
    document.getElementById('inputName').value = '';
    document.getElementById('inputNotes').value = '';
    document.getElementById('outputArea').innerHTML = '<div style="text-align:center; padding-top:100px; color:#111827; font-weight:800; letter-spacing:5px; font-size:0.7rem;">ENGINE STANDBY</div>';
    if(document.getElementById('mainApp').classList.contains('zen-active')) toggleZen();
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

async function copyIndividual(btn) {
    const text = btn.getAttribute('data-content');
    try {
        await navigator.clipboard.writeText(text);
        const originalText = btn.innerHTML;
        btn.innerHTML = 'COPIED!';
        btn.style.background = '#fff';
        setTimeout(() => { 
            btn.innerHTML = originalText; 
            btn.style.background = 'var(--accent)';
        }, 1000);
    } catch (e) { console.error(e); }
}

function forgePrompts() {
    const name = document.getElementById('inputName').value || "Holy";
    const style = document.getElementById('inputStyle').value;
    const notes = document.getElementById('inputNotes').value || "Professional, clean, sharp focus.";
    const out = document.getElementById('outputArea');
    out.innerHTML = '<div class="artifact-list"></div>';
    const list = out.querySelector('.artifact-list');

    for (let i = 1; i <= 10; i++) {
        const artifact = {
            id: `SIGN-PRO-V7.2-0${i}`,
            creator: "@holy",
            brand: "@circlemonth",
            config: { text: name, style: style, notes: notes },
            master_prompt: `Premium signature artifact: "${name}". Style: ${style}. Attributes: ${notes}. #${i}: Unique stroke dynamics, vector precision, isolated, 8k --v 6.1`
        };

        const jsonStr = JSON.stringify(artifact, null, 4);
        const card = document.createElement('div');
        card.className = 'artifact-card';
        card.innerHTML = `
            <div class="artifact-header">
                <div class="artifact-tag">FORGED 0${i}</div>
                <button class="copy-btn" onclick="copyIndividual(this)" data-content='${jsonStr.replace(/'/g, "&apos;")}'>COPY JSON</button>
            </div>
            <pre>${jsonStr}</pre>
        `;
        list.appendChild(card);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
}
//
